SET collation_connection = 'utf8mb4_0900_ai_ci';
DROP TRIGGER IF EXISTS trg_task_runs_terminal_outbox;
CREATE TRIGGER trg_task_runs_terminal_outbox AFTER UPDATE ON task_runs FOR EACH ROW INSERT INTO task_outbox_events (event_kind, aggregate, aggregate_id, event_type, stream_key, payload, status, dedup_key) SELECT 'event_store', 'task', NEW.task_id, IF(NEW.status = 'succeeded', 'TaskFinished', 'TaskFailed'), NULL, JSON_OBJECT('id', UUID(), 'aggregate', 'task', 'aggregate_id', NEW.task_id, 'event_type', IF(NEW.status = 'succeeded', 'TaskFinished', 'TaskFailed'), 'payload', JSON_OBJECT('account_id', NEW.account_id, 'lottery_id', NEW.lottery_id, 'success', IF(NEW.status = 'succeeded', true, false), 'mode', COALESCE(NEW.task_mode, ''), 'error', NEW.error_message, 'screenshot_path', NEW.screenshot_path, 'worker_id', COALESCE(NEW.worker_id, '')), 'correlation_id', NEW.task_id, 'causation_id', NULL, 'actor_type', 'system', 'actor_id', NULL, 'source_service', 'mysql-trigger'), 'pending', CONCAT('task-terminal-event:', NEW.task_id, ':', IF(NEW.status = 'succeeded', 'TaskFinished', 'TaskFailed')) WHERE OLD.status NOT IN ('succeeded', 'failed') AND NEW.status IN ('succeeded', 'failed') UNION ALL SELECT 'event_store', 'account', CAST(NEW.account_id AS CHAR), 'AccountExecutionFinished', NULL, JSON_OBJECT('id', UUID(), 'aggregate', 'account', 'aggregate_id', CAST(NEW.account_id AS CHAR), 'event_type', 'AccountExecutionFinished', 'payload', JSON_OBJECT('task_id', NEW.task_id, 'lottery_id', NEW.lottery_id, 'success', IF(NEW.status = 'succeeded', true, false), 'mode', COALESCE(NEW.task_mode, '')), 'correlation_id', NEW.task_id, 'causation_id', NULL, 'actor_type', 'system', 'actor_id', NULL, 'source_service', 'mysql-trigger'), 'pending', CONCAT('account-terminal-event:', NEW.task_id) WHERE OLD.status NOT IN ('succeeded', 'failed') AND NEW.status IN ('succeeded', 'failed') UNION ALL SELECT 'notify_stream', 'notification', NEW.task_id, 'NotifyEventRequested', 'notify_events', JSON_OBJECT('title', CONCAT('Task ', LEFT(NEW.task_id, 8), ' ', COALESCE(NEW.task_mode, ''), ' ', NEW.status), 'content', COALESCE(NEW.error_message, CONCAT('Lottery ', NEW.lottery_id, ' handled by account ', NEW.account_id, ' in ', COALESCE(NEW.task_mode, ''))), 'task_id', NEW.task_id, 'account_id', CAST(NEW.account_id AS CHAR), 'lottery_id', CAST(NEW.lottery_id AS CHAR), 'status', NEW.status, 'mode', COALESCE(NEW.task_mode, ''), 'channels', 'all'), 'pending', CONCAT('task-terminal-notify:', NEW.task_id, ':', NEW.status) WHERE OLD.status NOT IN ('succeeded', 'failed') AND NEW.status IN ('succeeded', 'failed');
